/**
 * AES-256-GCM-encrypted AsyncStorage wrapper.
 *
 * The encryption key is generated once per device and stored in
 * expo-secure-store (hardware-backed iOS Keychain / Android Keystore).
 * Each value gets a unique 12-byte IV (generated by expo-crypto).
 * Stored format in AsyncStorage: base64(IV + ciphertext + tag).
 *
 * Used by:
 *   - cache/index.ts for PHI (medication data, write-ahead log)
 *   - supabase/config.ts for the Supabase auth session (refresh + access tokens)
 *
 * Migration: legacy plaintext values written by older builds are detected on
 * read (they begin with `{` or `[` because they're JSON), encrypted in place,
 * and returned to the caller. Subsequent reads decrypt the ciphertext.
 */
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as SecureStore from 'expo-secure-store';
import {
  AESEncryptionKey,
  AESSealedData,
  aesEncryptAsync,
  aesDecryptAsync,
} from 'expo-crypto';

const SECURE_STORE_KEY = 'hlc_aes_key';

let _cachedKey: AESEncryptionKey | null = null;

async function getEncryptionKey(): Promise<AESEncryptionKey> {
  if (_cachedKey) return _cachedKey;

  const stored = await SecureStore.getItemAsync(SECURE_STORE_KEY);
  if (stored) {
    _cachedKey = await AESEncryptionKey.import(stored, 'base64');
    return _cachedKey;
  }

  const key = await AESEncryptionKey.generate(256);
  const exported = await key.encoded('base64');
  await SecureStore.setItemAsync(SECURE_STORE_KEY, exported);
  _cachedKey = key;
  return key;
}

function utf8ToBase64(str: string): string {
  const bytes = new TextEncoder().encode(str);
  let binary = '';
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function base64ToUtf8(b64: string): string {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new TextDecoder().decode(bytes);
}

async function encrypt(plaintext: string): Promise<string> {
  const key = await getEncryptionKey();
  const sealed = await aesEncryptAsync(utf8ToBase64(plaintext), key);
  return await sealed.combined('base64');
}

async function decrypt(ciphertext: string): Promise<string | null> {
  try {
    const key = await getEncryptionKey();
    const sealed = AESSealedData.fromCombined(ciphertext);
    const plainBase64 = await aesDecryptAsync(sealed, key, { output: 'base64' });
    return base64ToUtf8(plainBase64);
  } catch {
    return null;
  }
}

/** Encrypt and write a value to AsyncStorage. */
export async function secureSet(key: string, value: string): Promise<void> {
  const encrypted = await encrypt(value);
  await AsyncStorage.setItem(key, encrypted);
}

/**
 * Read and decrypt a value from AsyncStorage.
 * Returns null on cache miss or decryption failure.
 *
 * Auto-migrates legacy plaintext values: if the stored value looks like JSON,
 * it's re-encrypted in place before being returned.
 */
export async function secureGet(key: string): Promise<string | null> {
  const raw = await AsyncStorage.getItem(key);
  if (!raw) return null;
  if (raw.startsWith('{') || raw.startsWith('[')) {
    await secureSet(key, raw).catch(() => {});
    return raw;
  }
  return decrypt(raw);
}

/** Remove a value from AsyncStorage. Provided for adapter symmetry. */
export async function secureRemove(key: string): Promise<void> {
  await AsyncStorage.removeItem(key);
}
